How do forest fires spread?.code:
import random
random.seed(4)
N = 12
# 1 = tree, 0 = bare ground, 2 = fire
grid = [[1 if random.random() < 0.7 else 0 for _ in range(N)] for _ in range(N)]
grid[N // 2][N // 2] = 2

def step(g):
    new = [row[:] for row in g]
    for r in range(N):
        for c in range(N):
            if g[r][c] == 2:
                new[r][c] = 0
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < N and 0 <= cc < N and g[rr][cc] == 1:
                        if random.random() < 0.6:
                            new[rr][cc] = 2
    return new

for minute in range(6):
    show(grid, f"minute {minute}")
    grid = step(grid)
